 presidual_bits=math.log2(s0*DIMS["pyramid_presidual_modes"])
 E_total_zpe=E_zpe*DIMS["pyramid_presidual_modes"]
 h4=E_zpe>0 and presidual_bits>0 and _approx(omega,2*math.pi*DIMS["pyramid_presidual_freq_hz"])
