  v,f=_ann(0.20,0.18,-0.01,0.0,32);m.append(Mesh(v,f,_mix(C_TRAJECTORY,(80,140,255),0.5),"Earth orbit 1.0AU",alpha=80))
  # Ship glyph on the spiral at a mid-walk position + velocity arrow
