# SECTION 7d -- HYBRID CLASSICAL-QUANTUM OS (from Projectgoal.md)
# =============================================================================
class HybridOS:
 """Hybrid Classical-Quantum Operating System simulator.
 Classical OS receives commands, delegates quantum tasks to QuantumOS.
 Uses numpy instead of QuTiP for state vector simulation."""
 def __init__(s,num_qubits=5):
  s.num_qubits=num_qubits
  s.state=np.zeros(2**num_qubits,dtype=complex)
  s.state[0]=1.0  # |0...0>
  s.noise_level=0.01
  s.command_log=[]
  s.variables={}
  # Gate definitions (2x2 single-qubit gates)
  s._gates={
   'H':np.array([[1,1],[1,-1]],dtype=complex)/math.sqrt(2),
   'X':np.array([[0,1],[1,0]],dtype=complex),
   'Z':np.array([[1,0],[0,-1]],dtype=complex),
   'Y':np.array([[0,-1j],[1j,0]],dtype=complex),
   'S':np.array([[1,0],[0,1j]],dtype=complex),
   'T':np.array([[1,0],[0,np.exp(1j*math.pi/4)]],dtype=complex),
  }
 def _single_qubit_op(s,gate_matrix,target):
  """Apply a single-qubit gate to the multi-qubit state vector."""
  op_list=[np.eye(2,dtype=complex) for _ in range(s.num_qubits)]
  op_list[target]=gate_matrix
  full=op_list[0]
  for m in op_list[1:]:
   full=np.kron(full,m)
  s.state=full@s.state
 def _cnot_op(s,control,target):
  """Apply CNOT gate to the multi-qubit state vector."""
  dim=2**s.num_qubits
  full=np.zeros((dim,dim),dtype=complex)
  for i in range(dim):
   bits=format(i,f'0{s.num_qubits}b')
   if bits[control]=='1':
    new_bits=list(bits)
    new_bits[target]='1' if bits[target]=='0' else '0'
    j=int(''.join(new_bits),2)
    full[j,i]=1.0
   else:
    full[i,i]=1.0
  s.state=full@s.state
 def apply_gate(s,gate_name,target,control=None):
  if gate_name=='CNOT':
   if control is None:raise ValueError("CNOT requires control qubit")
   s._cnot_op(control,target)
  elif gate_name in s._gates:
   s._single_qubit_op(s._gates[gate_name],target)
  else:
   raise ValueError(f"Unknown gate: {gate_name}")
  s._apply_noise(target)
 def _apply_noise(s,target):
  """Physically valid depolarizing channel (opt2 Part II): with probability
  noise_level, apply a random Pauli {X,Y,Z} to the gate's target qubit --
  a true stochastic single-qubit depolarizing kick, not the old invalid
  depol.sqrtm()*state pattern."""
  if np.random.random()>=s.noise_level:return
  s._single_qubit_op(s._gates[('X','Y','Z')[int(np.random.randint(0,3))]],target)
 def measure(s,qubit,num_shots=1024):
  """Measure a qubit, returning SAMPLED counts (true binomial sampling,
  not deterministic analytic counts -- opt2 Part II)."""
  dim=2**s.num_qubits
  prob_0=0.0;prob_1=0.0
  for i in range(dim):
   bits=format(i,f'0{s.num_qubits}b')
   if bits[qubit]=='0':prob_0+=abs(s.state[i])**2
   else:prob_1+=abs(s.state[i])**2
  counts_0=int(np.random.binomial(num_shots,min(1.0,max(0.0,prob_0))))
  counts_1=num_shots-counts_0
  return{'0':counts_0,'1':counts_1}
 def execute_circuit(s,circuit):
  for gate in circuit:
   if len(gate)==2:s.apply_gate(gate[0],gate[1])
   elif len(gate)==3:s.apply_gate(gate[0],gate[1],gate[2])
  return"Circuit executed."
 def reset(s):
  s.state=np.zeros(2**s.num_qubits,dtype=complex)
  s.state[0]=1.0
 def execute_classical(s,cmd_parts):
  """Execute a classical OS command."""
  cmd=cmd_parts[0]
  s.command_log.append(' '.join(cmd_parts))
  if cmd=='print':
   return' '.join(cmd_parts[1:])
  elif cmd=='set':
   if len(cmd_parts)==3:
    s.variables[cmd_parts[1]]=cmd_parts[2]
    return f"Set {cmd_parts[1]} = {cmd_parts[2]}"
   return"Usage: set var value"
  elif cmd=='ls':
   return f"Variables: {list(s.variables.keys())}"
  elif cmd=='status':
   return f"Qubits: {s.num_qubits}, State norm: {np.linalg.norm(s.state):.4f}, Commands: {len(s.command_log)}"
  elif cmd=='reset':
   s.reset();return"Quantum state reset."
  return f"Unknown classical command: {cmd}"
 def execute_quantum(s,cmd_parts):
  """Delegate to quantum emulator."""
  s.command_log.append('quantum '+' '.join(cmd_parts))
  subcmd=cmd_parts[0]
  if subcmd=='apply':
   gate=cmd_parts[1];target=int(cmd_parts[2])
   control=int(cmd_parts[3]) if len(cmd_parts)>3 else None
   s.apply_gate(gate,target,control)
   return f"Applied {gate} to qubit {target}"
  elif subcmd=='measure':
   qubit=int(cmd_parts[1])
   results=s.measure(qubit)
   return f"Measurement on qubit {qubit}: {results}"
  elif subcmd=='run_circuit':
   circuit=[];i=1
   while i<len(cmd_parts):
    gate=cmd_parts[i]
    if gate=='CNOT':
     control=int(cmd_parts[i+1]);target=int(cmd_parts[i+2])
     circuit.append((gate,target,control));i+=3
    else:
     target=int(cmd_parts[i+1])
     circuit.append((gate,target));i+=2
   return s.execute_circuit(circuit)
  elif subcmd=='reset':
   s.reset();return"Quantum state reset."
  elif subcmd=='bell':
   # Prepare Bell state: H on q0, CNOT q0->q1
   s.apply_gate('H',0);s._cnot_op(0,1)
   return"Bell state |Phi+> prepared on qubits 0,1"
  elif subcmd=='vqe':
   # Simple VQE-like loop: H on q0, measure, classical feedback
   s.apply_gate('H',0)
   r=s.measure(0,100)
   return f"VQE iteration: H applied, measured {r}"
  return f"Unknown quantum subcommand: {subcmd}"
 def run_demo(s):
  """Run a demonstration of the hybrid OS."""
  results=[]
  results.append(s.execute_classical(['print','Initializing GmansQP Hybrid OS...']))
  results.append(s.execute_classical(['status']))
  # Prepare Bell state
  results.append(s.execute_quantum(['bell']))
  r=s.execute_quantum(['measure','0'])
  results.append(r)
  r2=s.execute_quantum(['measure','1'])
  results.append(r2)
  results.append(s.execute_classical(['print','Bell pair correlation verified.']))
  # VQE-like iteration
  results.append(s.execute_quantum(['vqe']))
  results.append(s.execute_classical(['status']))
  s.reset()
  return results

# === v3.0 CORRECTED EMULATOR + FABRIC (optimizedinfornmational2.md Part II) ===
# The ket-space QuantumOS is the canonical, physically-valid emulator: random
# Pauli depolarizing + true binomial sampling. HybridOS above carries the same
# corrected noise/measure semantics on its flat state-vector interface.

class QuantumOS:
 """Ket-space emulator with Monte-Carlo depolarizing noise (physically valid).
 opt2 Part II drop-in: tensor-product state, random-Pauli noise, sampled counts."""
 def __init__(s,num_qubits=3,noise=0.01,seed=None):
  s.n=num_qubits;s.noise=noise
  s.rng=np.random.default_rng(seed)
  s._paulis=np.array([[[1,0],[0,1]],[[0,1],[1,0]],
   [[0,-1j],[1j,0]],[[1,0],[0,-1]]],complex)
  s.reset()
 def reset(s):
  psi=np.zeros([2]*s.n,complex);psi[(0,)*s.n]=1.0
  s.psi=psi
 def _one(s,g,q):
  return np.moveaxis(np.tensordot(g,s.psi,axes=([1],[q])),0,q)
 def apply(s,name,target,control=None):
  g={'H':np.array([[1,1],[1,-1]])/np.sqrt(2),
   'X':s._paulis[1],'Z':s._paulis[3],
   'S':np.diag([1,1j]),'T':np.diag([1,np.exp(1j*np.pi/4)])}[name]
  if control is None:
   s.psi=s._one(g,target)
  else:
   t=target-(target>control)
   c0,c1=np.take(s.psi,0,control),np.take(s.psi,1,control)
   c1=np.moveaxis(np.tensordot(g,c1,axes=([1],[t])),0,t)
   s.psi=np.stack([c0,c1],axis=control)
  if s.rng.random()<s.noise:  # depolarizing: random Pauli on the target
   s.psi=s._one(s._paulis[s.rng.integers(1,4)],target)
 def measure(s,qubit,shots=1024):
  p0=float((np.abs(np.take(s.psi,0,axis=qubit))**2).sum())
  c0=int(s.rng.binomial(shots,p0))  # true sampling, not analytic counts
  return{'qubit':qubit,'counts':{'0':c0,'1':shots-c0},'p0':p0}

class ChipFabric:
 """N-die orchestrator -- linear scaling, no cross-talk assumed (opt2 Part II)."""
 def __init__(s,n_chips=5,qubits_per=3,noise=0.01,seed=0):
  s.chips=[QuantumOS(qubits_per,noise,seed=seed+i) for i in range(n_chips)]
 def run(s,chip_id,circuit):
  q=s.chips[chip_id]
  for op in circuit:
   q.apply(op[0],op[1],*(op[2:] or []))
  return"executed"
 def measure_all(s,shots=1024):
  return[q.measure(j,shots) for i,q in enumerate(s.chips) for j in range(q.n)]
 def throughput(s,acc_rate_per_qubit):
  return acc_rate_per_qubit*sum(q.n for q in s.chips)

def min_repetition(p_err,target=1e-9):
 """Smallest odd M whose majority-vote failure <= target (binomial tail).
 Returns (M, tail) -- opt2 Part II canonical form."""
 M=1
 while True:
  kmin=M//2+1
  tail=sum(math.comb(M,k)*p_err**k*(1-p_err)**(M-k) for k in range(kmin,M+1))
  if tail<=target:return M,tail
  M+=2

def lc_stabilize(phase_err,fidelity,threshold=0.999,vmax=10.0,kerr=2e-3):
 """Return (voltage, applied?). Bypasses when stabilization isn't needed
 (opt2 Part II canonical form)."""
 if fidelity>=threshold:
  return 0.0,False
 return min(abs(phase_err)/(2*np.pi*kerr),vmax),True

